mapper.select:
SELECT id, index_id, collection_type, source_type, source_id, vector_id,
       user_id, session_id, content_hash, status, failure_message,
       indexed_at, disabled_at, created_at, updated_at
FROM agent_vector_index
WHERE collection_type = #{collectionType}
  AND source_type = #{sourceType}
  AND source_id = #{sourceId}
LIMIT 1

mapper.update:
UPDATE agent_vector_index
SET status = 'DISABLED',
    disabled_at = CURRENT_TIMESTAMP,
    updated_at = CURRENT_TIMESTAMP
WHERE collection_type = #{collectionType}
  AND source_type = #{sourceType}
  AND source_id = #{sourceId}
